# FunctionGraph HTTP 函数(Python)
import json

def handler(event, context):
    return {
        "statusCode": 200,
        "headers": { "Content-Type": "application/json" },
        "body": json.dumps({ "hello": "whatsawesome" })
    }

# AWS Lambda(Python)
def lambda_handler(event, context):
    return {
        "statusCode": 200,
        "body": "Hello from Whats Awesome on AWS Lambda!"
    }

# Azure Functions HTTP 触发器(Python)
import azure.functions as func

def main(req: func.HttpRequest) -> func.HttpResponse:
    return func.HttpResponse("Hello from Whats Awesome on Azure Functions!")

# Google Cloud Functions(Python)
def hello_world(request):
    return "Hello from Whats Awesome on Google Cloud Functions!"

# GitCode OAuth 授权码流程
# 1. 跳转授权
GET https://gitcode.com/oauth/authorize?client_id={id}&redirect_uri={uri}&response_type=code&scope=user&state={rand}
# 2. 换 token
POST https://gitcode.com/oauth/token?grant_type=authorization_code&code={code}&client_id={id}&client_secret={secret}
# 3. 取用户信息
GET https://api.gitcode.com/api/v5/user  Authorization: Bearer {access_token}
